  // pull sources page (Elasticsearch / Loki / Splunk / Graylog / HTTP), restored from the Streamlit "Kaynaklar" page
  nav_sources: ["Veri kaynakları", "Data sources"], src_page: ["Veri kaynakları", "Data sources"], src_page_tag: ["Elasticsearch · OpenSearch · Grafana Loki · Splunk · Graylog · HTTP", "Elasticsearch · OpenSearch · Grafana Loki · Splunk · Graylog · HTTP"],
  src_n: ["kaynak", "sources"], src_active: ["etkin", "active"], src_err: ["hatalı", "failing"], src_name: ["Ad", "Name"], src_polls: ["sorgu", "polls"], src_off: ["duraklatıldı", "paused"], src_failing: ["hata veriyor", "failing"], src_toggle: ["Duraklat / sürdür", "Pause / resume"],
  src_intro: ["Watchover Elasticsearch, OpenSearch, Grafana Loki, Splunk, Graylog ya da herhangi bir HTTP ucunu düzenli aralıkla sorgular ve yeni kayıtları canlı akışa bir ajan göndermiş gibi ekler. Sunuculara ajan, platforma değişiklik gerekmez: salt okunur bir kullanıcı ve bir sorgu yeter. Her kaynak kendi ortam / site bilgisiyle adlandırılmış bir gönderici olur; filtreler ve kartlar onları ajanlar gibi ayırır.", "Watchover polls Elasticsearch, OpenSearch, Grafana Loki, Splunk, Graylog or any HTTP endpoint and streams new records into the live feed as if an agent had shipped them. No agent on the servers, no change on the platform: a read-only user and a query are enough. Each source becomes a named sender with its own environment / site, so filters and cards separate them like agents."],
  src_catalog: ["Hangi platformlar, ne gerekir, hangi loglar gelir", "Which platforms, what is needed, which logs come through"], src_needs: ["Gerekir", "Needs"], src_logs: ["Loglar", "Logs"],
  src_catalog_note: ["Her kayıt yükleme ve ajanlarla aynı parser'lardan geçer: JSON / ECS alanları eşlenir (zaman, seviye, host, servis, mesaj); düz metin satırları biçim tespitine girer (syslog, key=value, SAP trace, JVM, …). Kaynak başına imleç tutulur; yeniden başlatma aynı aralığı ikinci kez almaz.", "Every record goes through the same parsers as uploads and agents: JSON / ECS fields are mapped (timestamp, level, host, service, message); raw text lines are format-detected (syslog, key=value, SAP traces, JVM, …). Polling keeps a cursor per source, so restarts never re-import the same window."],
  src_needs_elasticsearch: ["Bir düğümün veya küme yük dengeleyicisinin adresi, sorgulanacak index deseni ve salt okunur bir kullanıcı ya da API anahtarı gerekir.", "The address of a node or the cluster load balancer, the index pattern to query and a read-only user or API key are required."],
  src_logs_elasticsearch: ["Filebeat, Logstash, Fluentd veya Vector ile indekslenmiş tüm kayıtlar ECS alanlarıyla ya da serbest alanlarla alınır.", "Every record indexed by Filebeat, Logstash, Fluentd or Vector is collected with ECS or free-form fields."],
  src_needs_opensearch: ["Elasticsearch ile aynı bilgiler gerekir; sorgu API'si birebir aynıdır.", "The same information as Elasticsearch is required; the query API is identical."], src_logs_opensearch: ["Elasticsearch ile aynı kayıtlar alınır.", "The same records as Elasticsearch are collected."],
  src_needs_loki: ["Loki adresi ve bir LogQL akış seçici gerekir; çok kiracılı kurulumlarda X-Scope-OrgID başlığı da eklenir.", "The Loki address and a LogQL stream selector are required; multi-tenant deployments also add the X-Scope-OrgID header."],
  src_logs_loki: ["Promtail, Alloy veya Fluent Bit tarafından gönderilen tüm akışlar alınır; host, instance, app ve job etiketleri sunucu ve servis bilgisine dönüşür.", "Every stream pushed by Promtail, Alloy or Fluent Bit is collected; the host, instance, app and job labels become host and service."],
  src_needs_splunk: ["Web portu yerine 8089 yönetim portu ile arama yetkisine sahip bir kullanıcı ya da kimlik doğrulama token'ı gerekir.", "The 8089 management port rather than the web port, together with a user holding search rights or an authentication token, is required."],
  src_logs_splunk: ["Tanımlanan aramanın döndürdüğü tüm olaylar host, source ve sourcetype alanlarıyla birlikte alınır.", "Every event returned by the configured search is collected with its host, source and sourcetype fields."],
  src_needs_graylog: ["REST API adresi ile bir kullanıcı hesabı ya da erişim token'ı gerekir.", "The REST API address and a user account or an access token are required."],
  src_logs_graylog: ["Kullanıcının okuma yetkisi olan tüm akışlardaki GELF ve syslog kayıtları mesaj, kaynak ve seviye bilgisiyle alınır.", "GELF and syslog records from every stream the user may read are collected with message, source and level."],
  src_needs_http: ["JSON listesi ya da düz log metni döndüren herhangi bir uç yeterlidir; Datadog, Sumo Logic, Papertrail dışa aktarımları ve kurum içi API'ler bu kapsama girer.", "Any endpoint returning a JSON list or plain log text is sufficient, including Datadog, Sumo Logic and Papertrail exports and in-house APIs."],
  src_logs_http: ["JSON kayıtlarının alanları otomatik eşlenir, düz metin satırları biçim tespitinden geçirilir ve adresteki {since} yer tutucusu imleçle değiştirilir.", "JSON record fields are mapped automatically, plain text lines pass through format detection and the {since} placeholder in the address is replaced by the cursor."],
  src_url_help: ["Platformun temel URL'si (şema, host, port). HTTP için tam uç; {since} / {since_epoch} imleçle değiştirilir.", "Base URL of the platform (scheme, host, port). For HTTP: the full endpoint; {since} / {since_epoch} are replaced by the cursor."],
  src_sel_help_elasticsearch: ["Index veya desen, virgülle: logs-*, filebeat-*", "Index or pattern, comma separated: logs-*, filebeat-*"], src_sel_help_opensearch: ["Index veya desen: logs-*", "Index or pattern: logs-*"],
  src_sel_help_loki: ["LogQL seçici, örn. {job=\"varlogs\"}", "LogQL selector, e.g. {job=\"varlogs\"}"], src_sel_help_splunk: ["Başında 'search' olmadan SPL: index=main sourcetype=syslog", "SPL without the leading 'search': index=main sourcetype=syslog"],
  src_sel_help_graylog: ["Graylog sorgu sözdizimi, örn. level:<=4 AND source:db*", "Graylog query syntax, e.g. level:<=4 AND source:db*"], src_sel_help_http: ["İsteğe bağlı: listeye giden JSON yolu: data.events", "Optional JSON path to the list: data.events"],
  src_auth_none: ["yok", "none"], src_auth_basic: ["kullanıcı + parola", "user + password"], src_auth_apikey: ["API anahtarı", "API key"], src_auth_bearer: ["bearer token", "bearer token"],
  src_secret_help: ["Şifreli saklanır; salt okunur hesap kullanın.", "Stored encrypted; use a read-only account."], src_advanced: ["Gelişmiş: geriye bakış, zaman alanı, ek başlıklar", "Advanced: lookback, timestamp field, extra headers"],
  src_verify_tls: ["TLS sertifikasını doğrula", "Verify TLS certificate"], src_lookback: ["İlk sorgu geriye bakış (dk)", "First poll looks back (min)"], src_ts_field: ["Zaman alanı (üzerine yaz)", "Timestamp field (override)"], src_headers: ["Ek başlıklar (satır başına Key: Value)", "Extra headers (Key: Value per line)"],
  src_save: ["Kaydet ve sorgulamaya başla", "Save and start polling"], src_list: ["Tanımlı kaynaklar", "Configured sources"], src_none: ["Henüz kaynak yok. Yukarıdan ekleyin; katalog her platform için ne gerektiğini anlatır.", "No source yet. Add one above; the catalogue explains what each platform needs."],
