  sys_rows: ["satır", "rows"], sys_tbl_filter: ["Tablo adı süz…", "Filter tables…"], sys_tbl_nonempty: ["Sadece dolu", "Non-empty only"], sys_tbl_more: ["{n} tablo daha ▾", "{n} more tables ▾"], sys_tbl_less: ["Daralt ▴", "Collapse ▴"],
  sys_cov: ["Parser kapsaması", "Parser coverage"], sys_cov_files: ["biçim", "formats"], sys_cov_score: ["puan", "score"], sys_cov_format: ["Algılanan", "Detected"], sys_cov_regress: ["gerileme", "regressions"],
  sys_cov_lead: ["Gürültü tablosu: örnek setlerde ham olay → sinyal → incident hunisi, azaltma katsayısı ve (alarm fırtınasında) gerçek listeye göre gürültü isabeti; parser değişince bu oran düşerse test kırmızı olur. Biçim korpusundaki her dosya (syslog, CEF, GELF, Apache, IIS, Windows, journald, Docker, Kubernetes, OTel, Cisco, Fortinet, Oracle, SQL Server, PostgreSQL, Java / Python / .NET / Go, HAProxy, Postfix, Redis, MongoDB, Kafka, AWS…) üretim parser'ından geçirilir; zaman, seviye, sunucu ve servis çıkarılan olay yüzdesi ölçülür. Puan dört alanın ortalaması; kabul edilen temel çizginin altına düşen değişiklik testte kalır.", "Noise table: raw events → signals → incidents on the sample datasets, the reduction factor and (alarm storm) noise precision against the ground truth; the tests go red when a parser change lowers it. Every file of the format corpus (syslog, CEF, GELF, Apache, IIS, Windows, journald, Docker, Kubernetes, OTel, Cisco, Fortinet, Oracle, SQL Server, PostgreSQL, Java / Python / .NET / Go, HAProxy, Postfix, Redis, MongoDB, Kafka, AWS…) goes through the production parser; the share of events with a timestamp, level, host and service is measured. The score averages the four; a change that drops below the accepted baseline fails the tests."],
  sys_cov_timestamp: ["zaman", "timestamp"], sys_cov_level: ["seviye", "level"], sys_cov_host: ["sunucu", "host"], sys_cov_service: ["servis", "service"], sys_cov_show: ["{n} biçimi göster ▾", "Show {n} formats ▾"],
