  // inventory page (restored from Streamlit)
  nav_inv: ["Envanter", "Inventory"], inv_page: ["Envanter", "Inventory"], inv_page_tag: ["sunucular · keşif · CSV", "hosts · discovery · CSV"], inv_hosts: ["sunucu", "hosts"], inv_critical: ["kritik", "critical"], inv_matched: ["canlı sunucu eşleşti", "live hosts matched"],
  inv_intro: ["Envanter, kurumun sunucu listesidir; bir log satırı geldiğinde operasyonun ihtiyaç duyduğu bilgilerle: konum (veri merkezi, kabin, VLAN), rol ve uygulama, sahip ekip, kritiklik, depolama. Gelen her olay sunucu adı, takma ad veya IP ile eşlenir: IP sunucu adına dönüşür, eksik ortam doldurulur, veri merkezi / kritiklik / sahip olayla birlikte motora (fırtına kümeleme, kritiklik puanı) ve kartlara taşınır. Elle, CMDB'nizin CSV dışa aktarımıyla ya da canlı akışta keşfedilen sunucuları terfi ettirerek doldurun.", "The inventory is the organisation's host list with what operations needs when a line arrives: location (data centre, rack, VLAN), role and application, owner, criticality, storage. Every incoming event is matched by hostname, alias or IP: an IP becomes its hostname, a missing environment is filled in, and data centre / criticality / owner travel with the event into the engine (storm clustering, criticality scoring) and the cards. Fill it by hand, from a CSV export of your CMDB, or by promoting hosts discovered in the live feed."],
  inv_tab_list: ["Sunucular", "Hosts"], inv_tab_add: ["Sunucu ekle", "Add host"], inv_tab_disc: ["Keşfedilenler", "Discovered"], inv_tab_csv: ["CSV içe / dışa aktar", "CSV import / export"], inv_search: ["Ara: db-01, 10.20., IST-DC1, oracle …", "Search: db-01, 10.20., IST-DC1, oracle …"],
  inv_none: ["Henüz sunucu yok: ekleyin, CSV yükleyin ya da keşfedilenleri terfi ettirin.", "No host yet: add one, import a CSV or promote discovered hosts."], inv_edit_title: ["{h} düzenle", "Edit {h}"],
  inv_disc_hint: ["Canlı akışta veya ajan kaydında görülen ama envanterin bilmediği sunucular. Tek tıkla ekleyin; kalanını sonra düzenleyin.", "Hosts seen in the live feed or the agent registry that the inventory does not know. Promote them with one click; edit the rest later."],
  inv_disc_none: ["Canlı akışta görülen her sunucu envanterde.", "Every host seen in the live feed is in the inventory."],
  inv_import_hint: ["Herhangi bir CMDB dışa aktarımı: sütunlar ada göre eşlenir (host / hostname / fqdn, ip, env / ortam, site / dc / veri_merkezi, rack / kabin, vlan / ağ, role / servis, owner / ekip, criticality / kritiklik, storage / depolama …). Var olan sunucular güncellenir.", "Any CMDB export: columns are matched by name (host / hostname / fqdn, ip, env, site / dc, rack, vlan / network, role / service, owner / team, criticality, storage …). Existing hosts are updated."],
  inv_import_go: ["İçe aktar", "Import"], inv_imported: ["{n} sunucu eklendi veya güncellendi", "{n} hosts imported or updated"], inv_template: ["CSV şablonu", "CSV template"], inv_export_hint: ["Envanterin tamamı, UTF-8 CSV.", "The whole inventory, UTF-8 CSV."], inv_export_go: ["Envanteri indir", "Download inventory"],
  inv_save: ["Kaydet", "Save"], inv_delete: ["Sil", "Delete"], inv_aliases_help: ["Logların bu sunucu için kullandığı diğer adlar (FQDN, kısa ad, eski ad), virgülle", "Other names the logs use for this host (FQDN, short name, old name), comma separated"], inv_role_help: ["veritabanı, uygulama sunucusu, web, depolama, ağ …", "database, app server, web, storage, network …"],
