  inv_f_role: ["Rol", "Role"], inv_f_application: ["Uygulama", "Application"], inv_f_cluster: ["Küme", "Cluster"], inv_f_owner: ["Sahip ekip", "Owner team"], inv_f_criticality: ["Kritiklik", "Criticality"], inv_f_storage: ["Depolama", "Storage"], inv_f_vendor_model: ["Üretici / model", "Vendor / model"], inv_f_serial: ["Seri no", "Serial"],
  inv_f_monitoring: ["İzleyen", "Monitored by"], inv_f_status: ["Durum", "Status"], inv_f_tags: ["Etiketler", "Tags"], inv_f_notes: ["Notlar", "Notes"],
  // parser patterns (grok)
  nav_parser: ["Parser desenleri", "Parser patterns"], gk_tag: ["grok kütüphanesi · kendi desenlerin · test · ayrıştırılamayan satırlar", "grok library · your patterns · test · unparsed lines"], gk_builtin: ["hazır paket", "built-in packs"], gk_user: ["kullanıcı deseni", "user patterns"], gk_user_one: ["kullanıcı", "user"],
  gk_intro: ["Grok, Logstash'in desen dili: %{IP:client} gibi adlandırılmış parçalar bir satırı alanlara ayırır. Hazır paketler (syslog, Apache, Squid, BIND, iptables, Nagios, ESXi, Tomcat, RabbitMQ, Docker, F5, Junos, Check Point, Zeek, Ruby, Node …) her dosyada otomatik denenir; dosyanın %60'ından fazlasıyla eşleşen desen o dosyanın parser'ı olur. Kendi uygulamanın satırı için deseni test kutusunda yazıp kaydet; kaydettiğin desen hazır paketlerden önce denenir.", "Grok is Logstash's pattern language: named pieces such as %{IP:client} split a line into fields. Built-in packs (syslog, Apache, Squid, BIND, iptables, Nagios, ESXi, Tomcat, RabbitMQ, Docker, F5, Junos, Check Point, Zeek, Ruby, Node …) are tried on every file; the pattern matching more than 60 % of a file becomes its parser. Write and test a pattern for your own application's lines and save it; saved patterns are tried before the built-in packs."],
  gk_tab_lib: ["Kütüphane", "Library"], gk_tab_test: ["Test", "Test"], gk_tab_unparsed: ["Ayrıştırılamayan satırlar", "Unparsed lines"], gk_tab_base: ["Temel parçalar", "Building blocks"], gk_add: ["Desen ekle", "Add pattern"],
  gk_family: ["Aile / servis", "Family / service"], gk_family_hint: ["Kayıt servis taşımıyorsa bu ad servis olur", "Becomes the service when the line carries none"], gk_roles: ["Roller", "Roles"], gk_corpus: ["Korpus", "Corpus"], gk_lines: ["satır", "lines"],
  gk_pattern: ["Desen", "Pattern"], gk_pattern_hint: ["Örnek: ^%{TIMESTAMP_ISO8601:timestamp} %{LOGLEVEL:severity} \\[%{DATA:service}\\] %{GREEDYDATA:message}$", "Example: ^%{TIMESTAMP_ISO8601:timestamp} %{LOGLEVEL:severity} \\[%{DATA:service}\\] %{GREEDYDATA:message}$"],
  gk_sample: ["Örnek satırlar", "Sample lines"], gk_run: ["Dene", "Run"], gk_save_as: ["Desen olarak kaydet", "Save as pattern"], gk_matched: ["{m} / {n} satır eşleşti", "{m} / {n} lines matched"], gk_fields: ["Alanlar", "Fields"], gk_line: ["Satır", "Line"], gk_nomatch: ["eşleşmedi", "no match"],
  gk_desc: ["Açıklama", "Description"], gk_roles_hint: ["Hangi yakalanan alan hangi rolü oynar: timestamp, severity, host, service, message; status (HTTP durum kodu → önem). Boş bırakılanlar öznitelik olarak kalır.", "Which captured field plays which role: timestamp, severity, host, service, message; status (HTTP status → severity). The rest stay as attributes."],
  gk_unparsed_hint: ["Bir veri setinde zaman damgası ya da açık seviyesi çıkarılamayan satırlar, şablonlarına göre gruplanmış. Bir örneği test kutusuna alıp desen yazın; kaydedince sonraki yüklemelerde tanınır.", "Lines of a dataset whose timestamp or explicit level could not be extracted, grouped by template. Take a sample into the test box and write a pattern; once saved, later uploads recognise it."],
  gk_pick_ds: ["Veri seti seç…", "Pick a dataset…"], gk_groups: ["grup", "groups"], gk_all_parsed: ["Bu setteki her satırın zamanı ve seviyesi çıkarıldı.", "Every line of this dataset has a timestamp and a level."], gk_no_ts: ["zaman yok", "no timestamp"], gk_no_level: ["seviye yok", "no level"], gk_use: ["Teste al", "Use in test"],
  gk_base_hint: ["Desenlerde %{AD} ya da %{AD:alan} olarak kullanılır; iç içe geçebilir.", "Use as %{NAME} or %{NAME:field} inside patterns; they nest."],
  // LLM review
  tab_llm_review: ["LLM incelemesi", "LLM review"], rv_title: ["LLM yorumu", "LLM review"], rv_lead: ["Kurulu LLM (Ollama ya da API) incident'ı, tüm veri setini ya da aradığın log satırlarını kanıtla birlikte okur ve görüşünü referanslarla yazar. Motorun deterministik kararı değişmez; bu ikinci bir göz.", "The configured LLM (Ollama or an API) reads the incident, the whole dataset or the log lines you search, together with the evidence, and writes its view with references. The engine's deterministic verdict does not change; this is a second opinion."],
  rv_run: ["LLM'e yorumlat", "Ask the LLM"], rv_running: ["Model düşünüyor…", "The model is thinking…"], rv_scope: ["Kapsam", "Scope"], rv_scope_dataset: ["Tüm veri seti", "Whole dataset"], rv_scope_incident: ["Incident", "Incident"], rv_scope_lines: ["Log satırları (arama)", "Log lines (search)"],
