  edit: ["Düzenle", "Edit"],
  tm_tab: ["Ekipler", "Teams"], tm_title: ["Ekipler ve sunucu grupları", "Teams and host groups"], tm_add: ["Yeni ekip", "New team"], tm_none: ["Henüz ekip yok: herkes bütün sunucuları görür.", "No team yet: everyone sees every host."],
  tm_lead: ["Bir ekip sunucularını kurallarla ya da elle sahiplenir. Ekibe eklenen kullanıcı canlı akış, anomaliler, APM, kullanıcı deneyimi, entegrasyonlar, envanter, ajanlar, haritalar ve asistanda yalnız o sunucuları ve onlarda çalışan servisleri görür. Yöneticiler ve 'Tüm sunucuları gör' yetkili roller hepsini görür.", "A team owns hosts by rules or by hand. A member then sees only those hosts and the services running on them, in the live feed, anomalies, APM, user experience, integrations, inventory, agents, maps and the assistant. Administrators and roles with 'See every host' see everything."],
  tm_name: ["Ekip", "Team"], tm_desc: ["Açıklama", "Description"], tm_rules: ["Kurallar", "Rules"], tm_rules_any: ["herhangi biri uyarsa sunucu ekibindir", "a host belongs to the team when any rule matches"], tm_hosts: ["Sunucu", "Hosts"], tm_members: ["Üyeler", "Members"],
  tm_explicit: ["elle", "by hand"], tm_explicit_hosts: ["Elle eklenen sunucular (virgülle)", "Hosts added by hand (comma separated)"], tm_rule_add: ["Kural ekle", "Add rule"], tm_preview: ["Önizleme", "Preview"], tm_preview_none: ["eşleşen sunucu yok", "no matching host"],
  tm_hint: ["Ekibi olmayan kullanıcılar her şeyi görür; Sistem › teams_strict açılırsa ekibi olmayanlar hiçbir sunucu görmez. Kurallar her 30 saniyede yeniden değerlendirilir: yeni bir ea-* sunucusu ajan bağlandığı anda EA ekibine düşer.", "Users in no team see everything; with System › teams_strict on, they see no host at all. Rules are re-evaluated every 30 seconds: a new ea-* host joins EA as soon as its agent connects."],
  nav_flows: ["İş akışları", "Business flows"], nav_exc: ["Hatalar", "Exceptions"],
  bf_title: ["İş akışları", "Business flows"], bf_sub: ["Bir iş anahtarı (sipariş, talep, başvuru no) birden çok sistemin logunda izlenir: hangi adımda kaç kayıt takıldı, nerede hata aldı.", "One business key (order, request, application no) followed across every system that logs it: where items wait and where they fail."],
  bf_new: ["Yeni akış", "New flow"], bf_edit: ["Akışı düzenle", "Edit flow"], bf_empty: ["Henüz iş akışı tanımlı değil. 'Yeni akış' ile bir anahtar deseni ve adımları tanımlayın; 'Öner' loglardan adımları çıkarır.", "No business flow yet. Define a key pattern and steps with 'New flow'; 'Suggest' derives the steps from the logs."],
  bf_k_items: ["İzlenen kayıt", "Items followed"], bf_k_done: ["Tamamlanma", "Completion"], bf_completed: ["tamamlandı", "completed"], bf_k_stuck: ["Takılan", "Stuck"], bf_k_stuck_sub: ["normal geçiş süresinin 1,5 katını aştı", "waited 1.5× the normal step time"],
  bf_k_err: ["Hata alan", "Failed"], bf_k_err_sub: ["anahtarı taşıyan hata satırı", "an error line carrying the key"], bf_key: ["Anahtar", "Key"], bf_funnel: ["Huni", "Funnel"], bf_from_prev: ["önceki adımdan", "of previous"], bf_start: ["başlangıç", "start"],
  bf_stuck: ["takıldı", "stuck"], bf_failed: ["hata", "failed"], bf_stuck_rule: ["Takılma eşiği adım bazında öğrenilir: son geçişlerin p95 süresinin 1,5 katı (en az 60 sn; veri azsa 15 dk).", "The stuck threshold is learned per step: 1.5× the p95 of recent transitions (at least 60 s; 15 min with little data)."],
