  bf_suggest: ["Öner", "Suggest"], bf_sugg_none: ["Son 24 saatte bu anahtarı taşıyan yeterli satır yok.", "Not enough lines carrying this key in the last 24 hours."], bf_sugg_lead: ["Anahtarı taşıyan mesaj kalıpları, bir kaydın yolundaki tipik sıralarıyla:", "Message templates carrying the key, in their usual order along an item's path:"],
