  rum_none: ["Henüz oturum yok. Uygulamalar sekmesinden bir uygulama ekleyip sensörü (web için tek satır script, mobil için SDK) yerleştirin; simülasyon da örnek İK oturumları üretir.", "No session yet. Add an app in the Apps tab and drop in the sensor (one script line for web, an SDK for mobile); the simulator produces sample HR sessions too."],
  rum_apps_title: ["Uygulamalar", "Apps"], rum_col_app: ["Uygulama", "App"], rum_col_views: ["Ekran / sayfa", "Screens / pages"], rum_col_avg: ["Ort. oturum", "Avg session"], rum_col_perf: ["Performans (p75)", "Performance (p75)"],
  rum_appstart: ["Açılış", "App start"], rum_slow_steps: ["En yavaş adımlar", "Slowest steps"], rum_col_step: ["Adım", "Step"], rum_top_errors: ["En sık hatalar ve çökmeler", "Top errors and crashes"], rum_no_errors: ["Hata yok.", "No errors."],
  rum_col_error: ["Hata", "Error"], rum_col_n: ["Adet", "Count"], rum_crash: ["çökme", "crash"], rum_error: ["hata", "error"],
  rum_kvkk: ["KVKK: kullanıcı kimlikleri kuruluma özel anahtarla takma ada çevrilir ve hiç saklanmaz; TCKN, telefon, e-posta, IBAN, kart ve parolalar maskelenir; adresler kimlik ve sorgu dizesi olmadan tutulur; IP adresi saklanmaz; form girdileri sensör tarafından hiç toplanmaz.", "KVKK / GDPR: user ids become keyed pseudonyms and are never stored; Turkish ID numbers, phones, e-mails, IBANs, cards and passwords are masked; URLs are kept without ids and query strings; IP addresses are not stored; form inputs are never collected by the sensors."],
  rum_all_platforms: ["Tüm platformlar", "All platforms"], rum_with_errors: ["Yalnız hatalı / çöken", "Errors / crashes only"], rum_no_sessions: ["Bu kapsamda oturum yok.", "No session in this scope."],
