  rum_lookup: ["Kullanıcının oturumlarını bul", "Find a user's sessions"], rum_lookup_hint: ["Bilinen bir kullanıcı kimliği (personel no, e-posta) takma adına çevrilir ve o kişinin oturumları süzülür. Kimlik saklanmaz; arama, gerekçesiyle birlikte güvenlik günlüğüne yazılır.", "A known user id (personnel number, e-mail) is turned into its pseudonym to filter that person's sessions. The id is not stored; the search and its reason go to the security log."],
  rum_lookup_user: ["Kullanıcı kimliği", "User id"], rum_lookup_reason: ["Gerekçe (ör. destek talebi numarası)", "Reason (e.g. support ticket number)"], rum_lookup_go: ["Bul", "Find"],
  rum_app_new: ["Yeni uygulama", "New app"], rum_platform: ["Platform", "Platform"], rum_origins: ["İzinli kökenler (web)", "Allowed origins (web)"], rum_sample: ["Örnekleme %", "Sample %"], rum_app_add: ["Ekle ve anahtar üret", "Add and create key"],
  rum_no_apps: ["Henüz uygulama yok.", "No app yet."], rum_key: ["Anahtar", "Key"], rum_any_origin: ["her köken", "any origin"], rum_snippet: ["Kurulum", "Setup"], rum_disable: ["Durdur", "Disable"], rum_enable: ["Aç", "Enable"], rum_rotate: ["Anahtarı yenile", "Rotate key"],
  rum_apps_hint: ["Anahtar sayfaya ya da uygulamaya gömülür, gizli değildir: web için izinli kökenler, mobil için yenileme ve durdurma ile korunur. Sensörler alıcıya (8600, edge açıksa 443) gönderir.", "The key is embedded in the page or app and is not a secret: web keys are bound to allowed origins, mobile keys can be rotated or disabled. Sensors post to the receiver (8600, or 443 with the edge)."],
  rum_snip_web: ["Sayfanın <head> kısmına ekleyin. Tıklamalar, sayfa geçişleri, fetch / XHR çağrıları ve Web Vitals kendiliğinden toplanır; aynı kökene giden çağrılara traceparent eklenir.", "Add to the page <head>. Clicks, route changes, fetch / XHR calls and Web Vitals are collected automatically; calls to the same origin get a traceparent header."],
  rum_snip_mobile: ["Başvuru SDK'sı depoda sensors/ altında; uygulamaya ekleyip bu satırlarla başlatın. Ekran geçişleri, ağ çağrıları (traceparent ile), açılış süresi ve çökmeler gönderilir.", "The reference SDK is in the repository under sensors/; add it to the app and start it with these lines. Screen changes, network calls (with traceparent), app start and crashes are sent."],
  rum_snip_kvkk: ["setUser ile verilen kimlik sunucuda takma ada çevrilir. Form değerleri, ekran içeriği, tuş vuruşları ve konum hiç toplanmaz.", "The id given to setUser is pseudonymised on the server. Form values, screen content, keystrokes and location are never collected."],
